from core import *

@register('differentiation','peano-kernel-sharp-error','Peano-kernel-total-variation','Taylor-integral-remainder-and-sign-changing-kernel','A quadrature error bound is the total variation of its Peano kernel, not the integral of that kernel; sharpness needs an approximating second derivative with its changing sign.','This bounds a linear error functional on arbitrary smooth functions, not a derivative value on a finite polynomial space.',[{'caseId':'kernel-root-'+str(q),'q':str(q),'purpose':'Move the two sign changes of the error kernel, changing cancellation and sharp norm.'} for q in [R(1,6),R(1,5),R(1,4),R(1,3),R(2,5),R(2,7),R(3,8),R(3,7)]],['integral Taylor remainder','signed kernels','sharp uniform bounds'])
def peano(case):
 q=R(case['q']);a=q*(1-q);b=1-a;pieces=[(0,a,t*t/2),(a,b,(t*t-t+a)/2),(b,1,(1-t)**2/2)];segments=[]
 for lo,hi,K in pieces:
  points=sorted({lo,hi,*[v for v in [q,1-q] if lo<v<hi]})
  for l,u in zip(points,points[1:]):segments.append((l,u,K,s.sign(K.subs(t,(l+u)/2))))
 A=s.factor(sum(sign*s.integrate(K,(t,lo,hi)) for lo,hi,K,sign in segments));signed=sum(s.integrate(K,(t,lo,hi)) for lo,hi,K in pieces)
 for j in [0,1]:ck('The quadrature annihilates a polynomial of degree '+str(j),s.integrate(x**j,(x,0,1))-(a**j+b**j)/2,0)
 for j in [2,3,4,5]:ck('Independent monomial error equals the kernel action at degree '+str(j),s.integrate(x**j,(x,0,1))-(a**j+b**j)/2,sum(s.integrate(K*j*(j-1)*t**(j-2),(t,lo,hi)) for lo,hi,K in pieces))
 condition('Both kernel roots lie strictly between the quadrature nodes',a<q<1-q<b,'The middle quadratic changes sign twice; its absolute integral must be split at these roots.')
 analytic('Exact sharp Peano norm',['The function is real and twice continuously differentiable on[0,1], with second derivative bounded by one.'],['Integral Taylor expansion at zero and exactness for affine functions give E(f)=integral K(t)f second(t)dt with the displayed piecewise kernel.','Therefore |E(f)|<=integral|K|. To approach this bound, approximate sign(K) by continuous functions bounded by one and integrate them twice. Dominated convergence makes the resulting errors approach integral|K|.','The kernel roots and signs are explicitly split, so the integral is evaluated without assuming a constant sign.'])
 return candidate(T('For real twice continuously differentiable functions on the unit interval satisfying ')+r'|f^{\prime\prime}(x)|\le1,'+T(' find the supremum of ')+r'\left|\int_0^1 f(x)\,\mathrm dx-\frac{f('+L(a)+r')+f('+L(b)+r')}{2}\right|.',A,[(abs(signed),'Use the signed kernel integral instead of its total variation'),(A/2,'Insert an extra factorial after already using the second-order integral remainder'),(2*A,'Forget the factorial in the second-order kernel'),(sum(abs(s.integrate(K,(t,lo,hi))) for lo,hi,K in pieces),'Take an absolute value only once per node interval, missing the internal roots'),(R(1,12),'Use the endpoint trapezoid bound for different nodes'),(R(1,24),'Use the midpoint bound for a two-node rule')],[T('The error annihilates affine functions. The integral Taylor remainder therefore expresses it as an integral against the second derivative.'),r'E(f)=\int_0^1K(t)f^{\prime\prime}(t)\,\mathrm dt,\qquad K(t)=\begin{cases}t^2/2&0\le t\le'+L(a)+r'\\(t^2-t+'+L(a)+r')/2&'+L(a)+r'\le t\le'+L(b)+r'\\(1-t)^2/2&'+L(b)+r'\le t\le1\end{cases}',r'K(t)=0\textnormal{ in the middle interval at }t='+L(q)+r',\ '+L(1-q),r'|E(f)|\le\int_0^1|K(t)|\,\mathrm dt='+L(A),T('Approximate the sign of the kernel by continuous functions bounded by one, and integrate twice to obtain admissible functions. Their errors approach the absolute kernel integral, proving the supremum.')],'sharp-second-derivative-quadrature-error-sign-kernel')

@register('differentiation','sturm-hurwitz-critical-count','Fourier-gap-forced-sign-changes','orthogonality-and-sign-matching-trigonometric-product','The lowest nonzero Fourier frequency forces a global number of critical points; the crucial step builds a lower-degree trigonometric polynomial with the same sign changes and contradicts orthogonality.','The exponential Chebyshev family is a maximum-zero theorem for nonoscillatory real exponentials. This is a minimum-zero theorem enforced by a spectral gap.',[{'caseId':'first-frequency-'+str(m),'m':m,'N':m+3,'purpose':'Different Fourier gaps with all higher coefficients unrestricted.'} for m in range(2,10)],['Fourier orthogonality','critical points','trigonometric polynomial degree'])
def sturm(case):
 m=case['m'];N=case['N'];A=s.Integer(2*m)
 for low in range(m):
  ck('The first available sine mode is orthogonal to cosine degree '+str(low),s.integrate(s.sin(m*x)*s.cos(low*x),(x,0,2*pi)),0)
  ck('The first available cosine mode is orthogonal to sine degree '+str(low),s.integrate(s.cos(m*x)*s.sin(low*x),(x,0,2*pi)),0)
 ck('The explicit attaining function has the stated derivative',s.diff(s.cos(m*x),x),-m*s.sin(m*x))
 analytic('Sturm-Hurwitz sign-change argument',['The trigonometric polynomial is real and its first frequency pair is not both zero. Thus its derivative is a nonzero real trigonometric polynomial.'],['The derivative is orthogonal over a full period to every trigonometric polynomial of degree less than m.','If it had only2r sign changes with r<m, multiply the factors sin((x-x_j)/2) over its cyclic sign-change locations. With2r factors this is a real periodic trigonometric polynomial of degree r. A global sign makes its product with the derivative nonnegative and positive on an open interval.','The resulting integral is strictly positive, contradicting orthogonality. Hence at least2m distinct derivative zeros exist. The function cos(mx) is admissible and has exactly2m critical points in a half-open period.'])
 return candidate(r'f(x)=\sum_{k='+str(m)+'}^{'+str(N)+r'}(a_k\cos kx+b_k\sin kx),\qquad a_k,b_k\in\mathbb R,\quad a_{'+str(m)+r'}^2+b_{'+str(m)+r'}^2>0.'+T('What is the smallest possible number of distinct critical points of f in ')+r'[0,2\pi)?',A,[(s.Integer(m),'Count only one of the two sign changes per lowest-frequency oscillation'),(s.Integer(2*m-2),'Permit one missing pair of sign changes despite the Fourier gap'),(s.Integer(2*m+2),'Require an additional oscillation that need not be present'),(s.Integer(2*N),'Use the highest allowed frequency as if its coefficient had to be nonzero'),(s.Integer(2*N+2),'Count both endpoints separately and use the largest allowed frequency'),(s.Integer(N-m+1),'Confuse the number of allowed frequencies with a zero count')],[T('The derivative has the same lowest nonzero Fourier frequency. It is orthogonal to every trigonometric polynomial of smaller degree.'),r'\int_0^{2\pi}f\prime(x)T(x)\,\mathrm dx=0\quad\textnormal{if }\deg T<'+str(m),T('Suppose there were fewer than the claimed number of sign changes. Pair their cyclic locations and multiply the half-angle sine factors. The resulting trigonometric polynomial has smaller degree and can be given the same sign as the derivative everywhere.'),r'T(x)=\pm\prod_{j=1}^{2r}\sin\frac{x-x_j}{2},\qquad r<'+str(m),r'f\prime(x)T(x)\ge0\quad\textnormal{everywhere, and it is positive on an open interval}',T('Its integral is then positive, a contradiction. Sign changes are distinct derivative zeros. Finally the following admissible function attains the bound.'),r'f(x)=\cos('+str(m)+r'x),\qquad f\prime(x)=-'+str(m)+r'\sin('+str(m)+r'x)'],'Fourier-gap-minimum-critical-point-count','nonnegative-integer')

@register('differentiation','dense-corner-series-derivative','summable-dense-corners-and-binary-orbit','dominated-difference-quotients-and-periodic-binary-residues','The summands have dense corners, so termwise differentiation needs a uniform summable Lipschitz majorant; the derivative value then depends on a periodic binary orbit.','An oscillatory single-function regularity threshold does not address infinitely many dense singular locations or the weighted orbit sum.',[{'caseId':'point-'+str(a)+'-ratio-'+str(lam),'a':str(a),'lam':str(lam),'purpose':'Different periodic binary orbits, all at nondyadic points, under a summable total slope budget.'} for a,lam in [(R(1,3),R(1,4)),(R(2,3),R(1,5)),(R(1,5),R(1,4)),(R(2,5),R(1,5)),(R(3,5),R(1,6)),(R(4,5),R(1,4)),(R(2,7),R(1,5)),(R(3,7),R(1,6))]],['uniform convergence','difference quotients','absolute-value derivatives','periodic residues'])
def corners(case):
 a=R(case['a']);lam=R(case['lam']);period=int(s.n_order(2,int(a.q)));eps=[]
 for j in range(1,period+1):
  left=s.floor((2**j*a+1)/2);eps.append(2*left-2**j*a)
 bulk=(a-R(1,2))*2*lam/(1-2*lam);osc=sum(eps[j-1]*lam**j for j in range(1,period+1))/(1-lam**period);A=s.factor(bulk+osc)
 for j in range(1,2*period+3):
  left=sum(int(bool(R(k,2**j)<a)) for k in range(1,2**j,2));actual=2*left-2**(j-1);model=(a-R(1,2))*2**j+eps[(j-1)%period]
  ck('Independent exact count of summand slopes at dyadic level '+str(j),actual,model)
 condition('The total Lipschitz majorant is summable',0<2*lam<1,'At level j there are2^(j-1) summands, each with Lipschitz constant lambda^j.')
 analytic('Differentiating a dense-corner series',['The evaluation point has odd denominator and is not dyadic. The ratio is strictly between zero and one half.'],['The function series converges uniformly on bounded intervals. Every difference quotient is bounded in absolute value by the summable level majorant2^(j-1)lambda^j. Since no corner equals the evaluation point, dominated convergence passes the derivative through the infinite sum.','At level j the derivative is lambda^j times the number of dyadic odd numerators to the left minus the number to the right. This count is2 floor((2^j a+1)/2)-2^(j-1).','Separate its linear2^j part from the bounded residue epsilon_j. The odd denominator makes the binary residue periodic, giving the two geometric sums displayed.'])
 return candidate(r'F(x)=\sum_{j=1}^{\infty}'+L(lam)+r'^j\sum_{\substack{1\le k<2^j\\k\textnormal{ odd}}}\left|x-\frac{k}{2^j}\right|.\qquad F\prime('+L(a)+r')',A,[(bulk,'Replace discrete dyadic counts by a continuous density, discarding the periodic residue'),(osc,'Keep only the periodic residue and discard the bulk slope'),(-A,'Reverse the signs of the absolute-value derivatives'),(A/2,'Use half the left-minus-right slope'),(2*A,'Count both even and odd numerators at every level'),(bulk+osc*(1-lam**period),'Count only the first residue period')],[T('No dyadic corner equals the evaluation point. The total Lipschitz constants are summable, so dominated convergence applies directly to the difference quotients.'),r'\sum_{j=1}^{\infty}2^{j-1}('+L(lam)+r')^j<\infty',r'F\prime(a)=\sum_{j\ge1}('+L(lam)+r')^j\left(2\left\lfloor\frac{2^ja+1}{2}\right\rfloor-2^{j-1}\right),\qquad a='+L(a),r'\varepsilon_j=2\left\lfloor\frac{2^ja+1}{2}\right\rfloor-2^ja,\qquad(\varepsilon_1,\ldots,\varepsilon_{'+str(period)+r'})=('+','.join(L(v) for v in eps)+r')',T('The displayed residue block repeats, because doubling has this period modulo the odd denominator.'),r'F\prime(a)=\left(a-\frac12\right)\frac{2\lambda}{1-2\lambda}+\frac{\sum_{j=1}^{'+str(period)+r'}\varepsilon_j\lambda^j}{1-\lambda^{'+str(period)+r'}},\qquad\lambda='+L(lam),L(bulk)+r'+\left('+L(osc)+r'\right)='+L(A)],'dense-dyadic-corner-series-nondyadic-derivative')

@register('differentiation','singular-implicit-branches','singular-curve-blowup-jets','tangent-cone-blowup-and-simple-branch-implicit-theorem','Ordinary implicit differentiation fails at the singular origin. Dividing after a tangent blowup separates the branches and reveals which derivative is actually determined.','The moving-root trace family starts with simple roots and sums them; this first resolves a singular plane curve with several distinct tangent directions.',[{'caseId':'tangent-cone-'+str(i),'roots':roots,'Q':Q,'purpose':'Different tangent configurations and nonlinear perturbation directions.'} for i,(roots,Q) in enumerate([([-2,1,3],[1,1,0,1]),([-3,0,2],[2,-1,1,0]),([-1,2,4],[1,0,2,1]),([-2,0,3],[3,1,1,0]),([-3,1,4],[2,2,0,1]),([-1,0,2],[1,-2,1,1]),([-4,-1,2],[3,0,1,1]),([-2,2,5],[2,1,-1,1])])],['analytic implicit functions','Taylor jets','singular points','blowup substitution'])
def singular_branches(case):
 roots=case['roots'];Q=sum(c*z**j for j,c in enumerate(case['Q']));P=s.prod(z-r for r in roots);F=s.expand(x**3*P.subs(z,y/x)+x**4*Q.subs(z,y/x));values=[-2*Q.subs(z,r)/s.diff(P,z).subs(z,r) for r in roots];A=sum(v*v for v in values)
 ck('The actual plane curve has the stated resolved equation',s.expand(F.subs(y,x*z)/x**3),P+x*Q)
 ck('The ordinary first implicit derivative is singular at the origin',s.diff(F,y).subs({x:0,y:0}),0)
 for r,v in zip(roots,values):
  ck('A branch jet cancels the first two curve orders for tangent '+str(r),s.expand(F.subs(y,r*x+v*x*x/2)).coeff(x,4),0)
  condition('The resolved tangent is simple',s.diff(P,z).subs(z,r)!=0,'The analytic implicit-function theorem applies after the tangent substitution.')
 analytic('Resolve the singular point before differentiating',['Only real analytic branches through the origin are requested, and the three displayed tangent roots are distinct and real.'],['Substitute y=xu for x not zero and cancel x^3. The resolved equation is P(u)+xQ(u)=0. Each simple real root r of P gives one analytic u branch with u(0)=r.','Conversely every analytic branch y through zero has a finite initial slope and hence one of these roots; there are exactly three.','Differentiate the resolved equation at zero to obtain u prime(0)=-Q(r)/P prime(r). Since y=xu, y second(0)=2u prime(0). Square and sum the three values.'])
 return candidate(r''+L(F)+r'=0.'+T('Let the real analytic branches through the origin be ')+r'y_1(x),y_2(x),y_3(x).'+T('Find ')+r'\sum_{j=1}^3(y_j^{\prime\prime}(0))^2.',A,[(A/4,'Use the derivative of the resolved slope as the second derivative of the original branch'),(A/2,'Apply only one of the two factors from squaring the second derivative'),(4*A,'Double the second derivative again before squaring'),(sum(values)**2,'Replace the sum of squares by the square of the sum'),(sum(abs(v) for v in values),'Sum derivative magnitudes instead of their squares'),(sum(v*v for v in values)/3,'Return an average over branches')],[T('At the origin the usual implicit derivative divides by zero. Resolve the tangent directions first.'),r'y=xu,\qquad\frac{F(x,xu)}{x^3}=P(u)+xQ(u),\quad P(u)='+L(P.subs(z,s.Symbol('u')))+r',\quad Q(u)='+L(Q.subs(z,s.Symbol('u'))),r'P(r)=0\quad\Longrightarrow\quad r\in\{'+','.join(map(str,roots))+r'\}',T('Each tangent root is simple, so the analytic implicit-function theorem gives precisely one resolved branch for each root.'),r'u\prime(0)=-\frac{Q(r)}{P\prime(r)},\qquad y^{\prime\prime}(0)=2u\prime(0)',r'(y_1^{\prime\prime}(0),y_2^{\prime\prime}(0),y_3^{\prime\prime}(0))=('+','.join(L(v) for v in values)+r')',r'\sum_j(y_j^{\prime\prime}(0))^2='+L(A)],'singular-analytic-plane-curve-tangent-blowup')

@register('differentiation','root-moment-extremum','real-root-reciprocal-moment-extremum','convex-exchange-and-attaining-root-configuration','A derivative constraint fixes the first reciprocal-root moment. The second derivative minimum comes from a box-constrained convex moment problem with an unavoidable residual root.','Log-derivative interlacing counts zeros globally; this optimizes a derivative over every allowed root configuration and must construct an attaining polynomial.',[{'caseId':'moment-box-'+str(i),'N':N,'lo':str(lo),'hi':str(hi),'S':str(S),'purpose':'Different degree and moment positions, including nonintegral endpoint occupancy.'} for i,(N,lo,hi,S) in enumerate([(4,1,3,R(15,2)),(5,1,2,R(33,4)),(5,R(1,2),2,R(29,4)),(6,1,3,R(23,2)),(6,R(1,2),R(3,2),R(25,4)),(7,1,2,R(47,4)),(7,R(1,3),R(4,3),R(29,4)),(8,R(1,2),2,R(43,4))])],['logarithmic derivative','polynomial roots','convexity','extremal configurations'])
def root_moments(case):
 N=case['N'];lo=R(case['lo']);hi=R(case['hi']);S=R(case['S']);j=int(s.floor((S-N*lo)/(hi-lo)));res=S-j*hi-(N-j-1)*lo;us=[hi]*j+[res]+[lo]*(N-j-1);square=sum(u*u for u in us);A=S*S-square
 # Exhaust all vertices independently: every vertex has at most one coordinate away from a box endpoint.
 vertices=[]
 for h in range(N):
  residual=S-h*hi-(N-h-1)*lo
  if lo<=residual<=hi:vertices.append(h*hi*hi+(N-h-1)*lo*lo+residual*residual)
 ck('Independent finite vertex enumeration gives the maximum reciprocal-square sum',max(vertices),square)
 poly=s.prod(1+u*x for u in us);ck('The explicit attaining polynomial has the required first derivative',s.diff(poly,x).subs(x,0),S);ck('Its second derivative independently matches the moment optimum',s.diff(poly,x,2).subs(x,0),A)
 condition('The first moment is strictly feasible and the residual lies in the box',N*lo<S<N*hi and lo<=res<=hi,'All roots are negative and repeated roots are permitted.')
 analytic('Convex box-slice moment extremum',['The polynomial is real of exactly the displayed degree, normalized to value one at zero; all roots lie in the displayed negative closed interval, with multiplicities allowed.'],['Write p(x)=product(1+u_j x), where each positive u_j lies between the reciprocal bounds. The first derivative fixes sum u_j=S, and the second equals S^2-sum u_j^2.','If two coordinates are interior to their bounds, shift an amount from the smaller one to the larger while preserving their sum; their square sum cannot decrease. Continue until at most one coordinate is interior.','Thus the maximum square sum is achieved with the displayed number at the upper bound, the remaining endpoints at the lower bound, and one residual coordinate. The constructed polynomial verifies attainment.'])
 return candidate(T('Let p be a real polynomial of degree ')+str(N)+T(', all of whose roots, with multiplicity, lie in ')+r'['+L(-1/lo)+','+L(-1/hi)+r'].'+r'\quad p(0)=1,\quad p\prime(0)='+L(S)+r'.'+T('What is the smallest possible value of ')+r'p^{\prime\prime}(0)?',A,[(A+sign*delta,('Double-count' if sign==1 else 'Omit')+' the ordered-pair contribution '+label) for delta,label in [(2*j*hi*res,'between upper endpoints and the residual root'),(2*(N-j-1)*lo*res,'between lower endpoints and the residual root'),(2*j*(N-j-1)*hi*lo,'between upper and lower endpoints')] for sign in [-1,1]],[r'p(x)=\prod_{j=1}^{'+str(N)+r'}(1+u_jx),\quad '+L(lo)+r'\le u_j\le'+L(hi)+r',\quad\sum_ju_j='+L(S),r'p^{\prime\prime}(0)=\left(\sum_ju_j\right)^2-\sum_ju_j^2',T('To minimize the derivative, maximize the sum of squares with the fixed sum. Moving mass from a smaller interior coordinate to a larger one increases that square sum, so at most one coordinate remains interior.'),r'(u_1,\ldots,u_{'+str(N)+r'})=('+','.join(L(u) for u in us)+r')\quad\textnormal{up to permutation}',r'\max\sum_ju_j^2='+L(square)+r',\qquad\min p^{\prime\prime}(0)='+L(S*S)+'-'+L(square)+'='+L(A),T('The product with these reciprocal roots satisfies every stated constraint, so the minimum is attained.')],'negative-root-box-fixed-first-derivative-second-extremum')

@register('differentiation','green-kernel-spectrum','Green-operator-spectrum','differentiate-integral-equation-and-solve-boundary-spectrum','An integral eigenfunction equation must be differentiated with its moving split point, and its endpoint conditions recovered before choosing the correct spectral branch.','The growing discrete cumulative-sum norm has the analogous boundary geometry, but here differentiation discovers a continuous boundary-value problem.',[{'caseId':'length-'+str(length)+'-'+boundary,'length':str(length),'boundary':boundary,'ordinal':j,'purpose':'Vary the interval length, Dirichlet versus natural boundary, and requested spectral index.'} for length,boundary,j in [(1,'mixed',1),(2,'mixed',2),(R(3,2),'mixed',3),(3,'mixed',2),(1,'dirichlet',2),(2,'dirichlet',3),(R(3,2),'dirichlet',1),(3,'dirichlet',4)]],['differentiation of split integrals','linear differential equations','boundary conditions','eigenvalues'])
def green(case):
 length=R(case['length']);bc=case['boundary'];j=case['ordinal'];freq=(2*j-1)*pi/(2*length) if bc=='mixed' else j*pi/length;A=freq**2;f=s.sin(freq*x)
 kernel=s.Min(x,t)-(x*t/length if bc=='dirichlet' else 0)
 # Independently integrate the actual split kernel against the candidate eigenfunction.
 v=s.integrate((t-(x*t/length if bc=='dirichlet' else 0))*s.sin(freq*t),(t,0,x))+s.integrate((x-(x*t/length if bc=='dirichlet' else 0))*s.sin(freq*t),(t,x,length))
 ck('Direct split integration verifies the actual integral eigenfunction',s.trigsimp(A*v),f)
 ck('The left endpoint condition holds',f.subs(x,0),0)
 ck('The recovered right endpoint condition holds',s.diff(f,x).subs(x,length) if bc=='mixed' else f.subs(x,length),0)
 analytic('Green-kernel differentiation and complete spectrum',['A nonzero real continuous eigenfunction on the closed interval is sought, and the eigenvalue is positive.'],['Split the minimum kernel integral at its moving endpoint. The first derivative is continuous, and the second derivative equals minus the integrand eigenfunction; hence f second+lambda f=0.','The integral equation imposes f(0)=0 and the displayed right endpoint condition. Thus f is a nonzero scalar multiple of sin(sqrt(lambda)x).','The right condition gives either the half-integer mixed-boundary frequencies or the integer Dirichlet frequencies. All positive solutions are ordered by their positive integer index. Direct split integration verifies the converse and excludes extraneous differential-equation solutions.'])
 Ktex=r'\min\{x,t\}'+(r'-\frac{xt}{'+L(length)+'}' if bc=='dirichlet' else '')
 return candidate(T('A nonzero real continuous function on ')+r'[0,'+L(length)+r']'+T(' satisfies ')+r'f(x)=\lambda\int_0^{'+L(length)+r'}\left('+Ktex+r'\right)f(t)\,\mathrm dt.'+T('What is the '+str(j)+('st' if j==1 else 'nd' if j==2 else 'rd' if j==3 else 'th')+' smallest positive value of ')+r'\lambda?',A,[((j*pi/length)**2,'Use two Dirichlet conditions for a mixed endpoint problem'),(((2*j-1)*pi/(2*length))**2,'Use a natural derivative condition instead of the stated kernel endpoint'),(((j+1)*pi/length)**2,'Start the positive spectral index one place too late'),(((2*j+1)*pi/(2*length))**2,'Advance the half-integer branch by one index'),(1/A,'Return the integral-operator eigenvalue rather than the multiplier in the equation'),(4*A,'Lose the half-interval frequency scale'),(A/4,'Insert a half-frequency scale twice')],[T('Split the minimum kernel at the moving endpoint and differentiate the two pieces. The boundary terms cancel in the first derivative.'),r'f^{\prime\prime}(x)=-\lambda f(x),\quad f(0)=0,\quad '+(r'f\prime('+L(length)+r')=0' if bc=='mixed' else r'f('+L(length)+r')=0'),r'f(x)=C\sin(\sqrt\lambda x),\qquad C\ne0',r'\sqrt{\lambda_k}='+((r'\frac{(2k-1)\pi}{2\cdot'+L(length)+r'}') if bc=='mixed' else r'\frac{k\pi}{'+L(length)+r'}')+r',\quad k=1,2,\ldots',T('These modes also satisfy the original integral equation, as direct integration of the split kernel confirms. Thus no extra differential-equation solutions have been introduced.'),r'\lambda_{'+str(j)+r'}='+L(A)],'integral-kernel-derived-continuous-boundary-spectrum')
